// Merge URLs and Topics data
const urls = $input.first().json;
const topics = $input.last().json;

// Get all topic values from the topics sheet
const topicList = $('Read Topics from Sheet').all().map(item => {
  return item.json.topic || item.json.Topic || Object.values(item.json)[0];
}).filter(topic => topic && topic.trim() !== '');

// Get all URLs from the URLs sheet
const urlList = $('Read URLs from Sheet').all().map(item => {
  return {
    url: item.json.url || item.json.URL || Object.values(item.json)[0],
    name: item.json.name || item.json.Name || Object.values(item.json)[1] || 'Unknown'
  };
}).filter(item => item.url && item.url.trim() !== '');

return {
  json: {
    urls: urlList,
    topics: topicList,
    topicsString: topicList.join(', ')
  }
};

// Extract and clean HTML content
const html = $input.item.json.data || $input.item.binary?.data?.toString('utf-8') || '';
const url = $('Split URLs').item.json.url;
const name = $('Split URLs').item.json.name;
const topics = $('Merge URLs and Topics').first().json.topics;

// Function to strip HTML tags and clean text
function stripHtml(html) {
  if (!html) return '';

  // Remove script and style tags with their content
  let text = html.replace(/<script[^>]*>([\s\S]*?)<\/script>/gi, '');
  text = text.replace(/<style[^>]*>([\s\S]*?)<\/style>/gi, '');

  // Remove HTML tags
  text = text.replace(/<[^>]+>/g, ' ');

  // Decode HTML entities
  text = text.replace(/&nbsp;/g, ' ');
  text = text.replace(/&amp;/g, '&');
  text = text.replace(/&lt;/g, '<');
  text = text.replace(/&gt;/g, '>');
  text = text.replace(/&quot;/g, '"');
  text = text.replace(/&#39;/g, "'");
  text = text.replace(/&#(\d+);/g, (match, dec) => String.fromCharCode(dec));

  // Clean up whitespace
  text = text.replace(/\s+/g, ' ');
  text = text.trim();

  return text;
}

// Function to extract potential event information
function extractEvents(text, topics) {
  const events = [];
  const sentences = text.split(/[.!?]+/);

  // Keywords that might indicate events
  const eventKeywords = [
    'event', 'conference', 'meeting', 'workshop', 'seminar', 'webinar',
    'summit', 'forum', 'symposium', 'exhibition', 'fair', 'festival',
    'ceremony', 'celebration', 'gathering', 'session', 'presentation',
    'date', 'when', 'where', 'time', 'location', 'venue', 'schedule',
    'january', 'february', 'march', 'april', 'may', 'june',
    'july', 'august', 'september', 'october', 'november', 'december',
    'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday',
    '2024', '2025', '2026'
  ];

  // Check each sentence for event-related content and topic relevance
  sentences.forEach(sentence => {
    const lowerSentence = sentence.toLowerCase();

    // Check if sentence contains event keywords
    const hasEventKeyword = eventKeywords.some(keyword => 
      lowerSentence.includes(keyword)
    );

    // Check if sentence contains any of the topics
    const relatedTopics = topics.filter(topic => 
      lowerSentence.includes(topic.toLowerCase())
    );

    // If both conditions are met, consider it a potential event
    if (hasEventKeyword && relatedTopics.length > 0 && sentence.trim().length > 20) {
      events.push({
        text: sentence.trim(),
        relatedTopics: relatedTopics,
        confidence: relatedTopics.length > 1 ? 'high' : 'medium'
      });
    }
  });

  return events;
}

// Clean the HTML
const cleanText = stripHtml(html);

// Extract events
const extractedEvents = extractEvents(cleanText, topics);

// Return results
return {
  json: {
    sourceUrl: url,
    sourceName: name,
    eventsFound: extractedEvents.length,
    events: extractedEvents,
    scrapedAt: new Date().toISOString(),
    topics: topics,
    contentPreview: cleanText.substring(0, 500) + '...'
  }
};
